def correct_wheel_speeds(left_counts, right_counts, target_speed, gain=1):
    if isinstance(left_counts, (str, bytes)) or not hasattr(left_counts, "__iter__"):
        raise TypeError("left_counts must be a sequence")
    if isinstance(right_counts, (str, bytes)) or not hasattr(right_counts, "__iter__"):
        raise TypeError("right_counts must be a sequence")
    if isinstance(target_speed, bool) or not isinstance(target_speed, int):
        raise TypeError("target_speed must be an integer")
    if isinstance(gain, bool) or not isinstance(gain, int):
        raise TypeError("gain must be an integer")
    if not 0 <= target_speed <= 100:
        raise ValueError("target_speed must be between 0 and 100")
    if gain < 0:
        raise ValueError("gain must be non-negative")

    left = list(left_counts)
    right = list(right_counts)
    if len(left) != len(right):
        raise ValueError("encoder sequences must have equal length")

    for readings in (left, right):
        previous = None
        for count in readings:
            if isinstance(count, bool) or not isinstance(count, int):
                raise TypeError("encoder counts must be integers")
            if count < 0:
                raise ValueError("encoder counts must be non-negative")
            if previous is not None and count < previous:
                raise ValueError("encoder counts must not decrease")
            previous = count

    if not left:
        return []

    result = []
    for left_count, right_count in zip(left, right):
        drift = (left_count - left[0]) - (right_count - right[0])
        left_speed = max(0, min(100, target_speed + gain * drift))
        right_speed = max(0, min(100, target_speed - gain * drift))
        result.append((left_speed, right_speed))
    return result

